import re
from collections import Counter

def word_frequencies(text: str) -> dict:
    """
    Return a dictionary mapping each lowercase word in *text* to its frequency.
    Punctuation is ignored and words are split on any non‑alphanumeric characters.
    """
    # Find all alphanumeric sequences, convert to lower case
    words = re.findall(r'\b\w+\b', text.lower())
    # Count occurrences
    return dict(Counter(words))


# ---- Test cases -------------------------------------------------
if __name__ == "__main__":
    assert word_frequencies('a b a') == {'a': 2, 'b': 1}
    assert word_frequencies('Hi, hi!') == {'hi': 2}
    assert word_frequencies('') == {}
    print("All tests passed.")
```

This implementation uses a regular expression to extract words, lowers the case, counts them with `collections.Counter`, and returns a plain dictionary as required. The three assertions supplied in the prompt all succeed.
